@@ -0,0 +1,166 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "edgecolorsampler.h"
+
+#include <QCoreApplication>
+#include <QImageReader>
+#include <QPointer>
+#include <QThreadPool>
+#include <QUrl>
+
+// Values of Image.fillMode in QML
+constexpr int PreserveAspectFit = 1;
+constexpr int Pad = 6;
+
+static QColor sampleEdgeColor(const QString &source, const QSize &targetSize, int fillMode)
+{
+    if (fillMode != PreserveAspectFit && fillMode != Pad) {
+        return Qt::transparent;
+    }
+
+    QImageReader reader(QUrl::fromUserInput(source).toLocalFile());
+    reader.setAutoTransform(true);
+    if (fillMode == PreserveAspectFit && (reader.size().width() > targetSize.width() || reader.size().height() > targetSize.height())) {
+        reader.setScaledSize(reader.size().scaled(targetSize, Qt::KeepAspectRatio));
+    }
+
+    const QImage image = reader.read();
+    if (image.isNull()) {
+        return Qt::transparent;
+    }
+
+    QRect visibleRect = image.rect();
+    bool leftAndRight = false;
+    bool topAndBottom = false;
+
+    if (fillMode == PreserveAspectFit) {
+        const qint64 imageWidth = qint64(image.width()) * targetSize.height();
+        const qint64 targetWidth = qint64(targetSize.width()) * image.height();
+        leftAndRight = imageWidth < targetWidth;
+        topAndBottom = imageWidth > targetWidth;
+    } else {
+        const QSize visibleSize = image.size().boundedTo(targetSize);
+        visibleRect = QRect(QPoint((image.width() - visibleSize.width()) / 2, (image.height() - visibleSize.height()) / 2), visibleSize);
+        leftAndRight = image.width() < targetSize.width();
+        topAndBottom = image.height() < targetSize.height();
+    }
+
+    QList<QRect> strips;
+    if (leftAndRight) {
+        const int thickness = std::clamp(visibleRect.width() / 50, 1, 16);
+        strips << QRect(visibleRect.left(), visibleRect.top(), thickness, visibleRect.height());
+        strips << QRect(visibleRect.right() - thickness + 1, visibleRect.top(), thickness, visibleRect.height());
+    }
+    if (topAndBottom) {
+        const int thickness = std::clamp(visibleRect.height() / 50, 1, 16);
+        strips << QRect(visibleRect.left(), visibleRect.top(), visibleRect.width(), thickness);
+        strips << QRect(visibleRect.left(), visibleRect.bottom() - thickness + 1, visibleRect.width(), thickness);
+    }
+
+    qint64 red = 0;
+    qint64 green = 0;
+    qint64 blue = 0;
+    qint64 weight = 0;
+    for (const QRect &strip : std::as_const(strips)) {
+        for (int y = strip.top(); y <= strip.bottom(); ++y) {
+            for (int x = strip.left(); x <= strip.right(); ++x) {
+                const QColor color = image.pixelColor(x, y);
+                red += color.red() * color.alpha();
+                green += color.green() * color.alpha();
+                blue += color.blue() * color.alpha();
+                weight += color.alpha();
+            }
+        }
+    }
+
+    if (weight == 0) {
+        return Qt::transparent;
+    }
+
+    return QColor(red / weight, green / weight, blue / weight);
+}
+
+EdgeColorSampler::EdgeColorSampler(QObject *parent)
+    : QObject(parent)
+{
+}
+
+QString EdgeColorSampler::source() const
+{
+    return m_source;
+}
+
+void EdgeColorSampler::setSource(const QString &source)
+{
+    if (m_source != source) {
+        m_source = source;
+        Q_EMIT sourceChanged();
+        update();
+    }
+}
+
+QSize EdgeColorSampler::targetSize() const
+{
+    return m_targetSize;
+}
+
+void EdgeColorSampler::setTargetSize(const QSize &size)
+{
+    if (m_targetSize != size) {
+        m_targetSize = size;
+        Q_EMIT targetSizeChanged();
+        update();
+    }
+}
+
+int EdgeColorSampler::fillMode() const
+{
+    return m_fillMode;
+}
+
+void EdgeColorSampler::setFillMode(int fillMode)
+{
+    if (m_fillMode != fillMode) {
+        m_fillMode = fillMode;
+        Q_EMIT fillModeChanged();
+        update();
+    }
+}
+
+QColor EdgeColorSampler::color() const
+{
+    return m_color;
+}
+
+void EdgeColorSampler::setColor(const QColor &color)
+{
+    if (m_color != color) {
+        m_color = color;
+        Q_EMIT colorChanged();
+    }
+}
+
+void EdgeColorSampler::update()
+{
+    const int generation = ++m_generation;
+    if (m_source.isEmpty() || m_targetSize.isEmpty()) {
+        setColor(Qt::transparent);
+        return;
+    }
+
+    QThreadPool::globalInstance()->start([self = QPointer(this), generation, source = m_source, targetSize = m_targetSize, fillMode = m_fillMode] {
+        const QColor color = sampleEdgeColor(source, targetSize, fillMode);
+        QMetaObject::invokeMethod(
+            qApp,
+            [self, generation, color] {
+                if (self && self->m_generation == generation) {
+                    self->setColor(color);
+                }
+            },
+            Qt::QueuedConnection);
+    });
+}
diff --git a/wallpapers/potd/plugins/edgecolorsampler.h b/wallpapers/potd/plugins/edgecolorsampler.h
new file mode 100644
index 000000000..0246faab1
--- /dev/null
+++ b/wallpapers/potd/plugins/edgecolorsampler.h
@@ -0,0 +1,60 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QColor>
+#include <QObject>
+#include <QSize>
+#include <qqmlregistration.h>
+
+/**
+ * Finds the average color of the edges of an image that border the empty area around it
+ * when it is shown with the given fill mode in an area of the given size.
+ */
+class EdgeColorSampler : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+
+    Q_PROPERTY(QString source READ source WRITE setSource NOTIFY sourceChanged)
+    Q_PROPERTY(QSize targetSize READ targetSize WRITE setTargetSize NOTIFY targetSizeChanged)
+    Q_PROPERTY(int fillMode READ fillMode WRITE setFillMode NOTIFY fillModeChanged)
+    /**
+     * The edge color, or transparent if the fill mode leaves no empty area or the image can't be read.
+     */
+    Q_PROPERTY(QColor color READ color NOTIFY colorChanged)
+
+public:
+    explicit EdgeColorSampler(QObject *parent = nullptr);
+
+    QString source() const;
+    void setSource(const QString &source);
+
+    QSize targetSize() const;
+    void setTargetSize(const QSize &size);
+
+    int fillMode() const;
+    void setFillMode(int fillMode);
+
+    QColor color() const;
+
+Q_SIGNALS:
+    void sourceChanged();
+    void targetSizeChanged();
+    void fillModeChanged();
+    void colorChanged();
+
+private:
+    void update();
+    void setColor(const QColor &color);
+
+    QString m_source;
+    QSize m_targetSize;
+    int m_fillMode = 0;
+    QColor m_color = Qt::transparent;
+    int m_generation = 0;
+};
